const int NUM_HCICONS = (int)(sizeof(HCICONS)/sizeof(HCICONS[0]));

/* ==================== catalogue de la pile ==================== */

/* Copie de travail des icones de la pile courante. On copie plutot que de
 * pointer dans la structure de la pile : hcicon_find rend un pointeur que
 * l'appelant garde le temps d'un dessin, et une pile rechargee entre-temps
 * le laisserait pendre. Le cout est nul a cette echelle — quelques dizaines
 * d'icones de 128 octets. */
static HCIcon *gStackIcons = NULL;
static int     gStackCount = 0;

static void hcicon_free_stack_icons(void) {
    for (int i = 0; i < gStackCount; i++)
        free((void *)gStackIcons[i].name);   /* strdup ci-dessous */
    free(gStackIcons);
    gStackIcons = NULL;
    gStackCount = 0;
}

void hcicon_use_stack_icons(const struct StackIcon *tab, int n) {
    hcicon_free_stack_icons();
    if (!tab || n <= 0) return;

    gStackIcons = calloc((size_t)n, sizeof *gStackIcons);
    if (!gStackIcons) return;

    for (int i = 0; i < n; i++) {
        gStackIcons[i].id   = tab[i].id;
        gStackIcons[i].name = strdup(tab[i].name ? tab[i].name : "");
        memcpy(gStackIcons[i].bits, tab[i].bits, 128);
    }
    gStackCount = n;
}

int hcicon_stack_count(void) { return gStackCount; }

const HCIcon *hcicon_stack_at(int i) {
    if (i < 0 || i >= gStackCount) return NULL;
    return &gStackIcons[i];
}

const HCIcon *hcicon_find(int id) {
    /* La pile d'abord : c'est ce qui permet de redefinir une icone d'origine
     * sans recompiler. Parcours a rebours, la derniere entree lue l'emporte
     * si un fichier abime contient deux fois le meme numero. */
    for (int i = gStackCount - 1; i >= 0; i--)
        if (gStackIcons[i].id == id) return &gStackIcons[i];
    for (int i = 0; i < NUM_HCICONS; i++)
        if (HCICONS[i].id == id) return &HCICONS[i];
    return NULL;
}

int hcicon_builtin_has(int id) {
    for (int i = 0; i < NUM_HCICONS; i++)
        if (HCICONS[i].id == id) return 1;
    return 0;
}

/* Comparaison de noms d'icones : casse ignoree, espaces de bord ignores.
 * On ne se sert pas de strcasecmp directement pour pouvoir rogner les bords
 * sans recopier la chaine. */
static int hcicon_name_eq(const char *a, const char *b) {
    if (!a || !b) return 0;
    while (*a == ' ' || *a == '\t') a++;
    while (*b == ' ' || *b == '\t') b++;
    const char *ea = a + strlen(a), *eb = b + strlen(b);
    while (ea > a && (ea[-1] == ' ' || ea[-1] == '\t')) ea--;
    while (eb > b && (eb[-1] == ' ' || eb[-1] == '\t')) eb--;
    if ((ea - a) != (eb - b)) return 0;
    for (; a < ea; a++, b++)
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) return 0;
    return 1;
}

int hcicon_id_for_text(const char *s) {
    if (!s) return 0;
    while (*s == ' ' || *s == '\t') s++;
    if (!*s) return 0;

    /* Un nombre, eventuellement signe : HyperCard acceptait les deux formes,
     * et un nom d'icone ne commence jamais par un chiffre. */
    if (*s == '-' || (*s >= '0' && *s <= '9')) {
        char *end = NULL;
        long v = strtol(s, &end, 10);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end && !*end) return (int)v;
        /* sinon c'est un nom qui commence par un chiffre : on continue */
    }

    for (int i = 0; i < gStackCount; i++)
        if (hcicon_name_eq(gStackIcons[i].name, s)) return gStackIcons[i].id;
    for (int i = 0; i < NUM_HCICONS; i++)
        if (hcicon_name_eq(HCICONS[i].name, s)) return HCICONS[i].id;
    return 0;
}

/* ---- catalogue complet ----
 * On ne construit aucune table : le catalogue est la concatenation de celle
 * de la pile et de celle d'origine, moins les doublons. L'index se traduit
 * donc a la volee. Une table de plus serait une table de plus a invalider,
 * et c'est exactement le genre d'oubli qui laisse une vue sur une icone
 * disparue. */
static int hcicon_builtin_is_overridden(int id) {
    for (int i = 0; i < gStackCount; i++)
        if (gStackIcons[i].id == id) return 1;
    return 0;
}

int hcicon_catalog_count(void) {
    int n = gStackCount;
    for (int i = 0; i < NUM_HCICONS; i++)
        if (!hcicon_builtin_is_overridden(HCICONS[i].id)) n++;
    return n;
}

const HCIcon *hcicon_catalog_at(int i) {
    if (i < 0) return NULL;
    if (i < gStackCount) return &gStackIcons[i];

    int k = i - gStackCount;
    for (int j = 0; j < NUM_HCICONS; j++) {
        if (hcicon_builtin_is_overridden(HCICONS[j].id)) continue;
        if (k-- == 0) return &HCICONS[j];
    }
    return NULL;
}

/* Marque les pixels eteints que l'on atteint depuis le bord de la grille.
 * Ce qui reste eteint sans etre marque est ENCLOS dans le dessin. */
static void icon_outside(const HCIcon *ic, unsigned char out[32][32]) {
    memset(out, 0, 32 * 32);

    /* Pile explicite plutot que recursion : 1024 cases au pire, et l'on ne
     * risque pas de faire deborder celle du programme. */
    static short pile[1024 * 2];
    int sp = 0;

    for (int i = 0; i < 32; i++) {
        int bords[4][2] = { {0,i}, {31,i}, {i,0}, {i,31} };
        for (int k = 0; k < 4; k++) {
            int r = bords[k][0], c = bords[k][1];
            if (ic->bits[r*4 + c/8] & (0x80 >> (c & 7))) continue;  /* encre */
            if (out[r][c]) continue;
            out[r][c] = 1;
            pile[sp*2] = (short)r; pile[sp*2+1] = (short)c; sp++;
        }
    }

    while (sp > 0) {
        sp--;
        int r = pile[sp*2], c = pile[sp*2+1];
        int dr[4] = {-1,1,0,0}, dc[4] = {0,0,-1,1};
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr > 31 || nc < 0 || nc > 31) continue;
            if (out[nr][nc]) continue;
            if (ic->bits[nr*4 + nc/8] & (0x80 >> (nc & 7))) continue;
            out[nr][nc] = 1;
            if (sp < 1024) { pile[sp*2] = (short)nr; pile[sp*2+1] = (short)nc; sp++; }
        }
    }
}

void hcicon_draw_inverted(const HCIcon *ic, NSRect r, CGFloat px) {
    if (!ic) return;

    unsigned char dehors[32][32];
    icon_outside(ic, dehors);

    /* Meme centrage que hcicon_draw : les deux doivent coincider au point
     * pres, sinon l'inversion se decalerait du dessin. */
    CGFloat ox = r.origin.x + (r.size.width  - 32*px) / 2;
    CGFloat oy = r.origin.y + (r.size.height - 32*px) / 2;

    for (int row = 0; row < 32; row++) {
        for (int col = 0; col < 32; col++) {
            int encre = (ic->bits[row*4 + col/8] & (0x80 >> (col & 7))) ? 1 : 0;
            if (!encre && dehors[row][col]) continue;      /* le fond ne bouge pas */

            [(encre ? [NSColor whiteColor] : [NSColor blackColor]) setFill];
            NSRectFill(NSMakeRect(ox + col*px, oy + row*px, px, px));
        }
    }
}

void hcicon_draw(const HCIcon *ic, NSRect r, CGFloat px) {
    if (!ic) return;
   
    CGFloat ox = r.origin.x + (r.size.width  - 32*px) / 2;
    CGFloat oy = r.origin.y + (r.size.height - 32*px) / 2;
    for (int row = 0; row < 32; row++) {
        for (int col = 0; col < 32; col++) {
            unsigned char byte = ic->bits[row*4 + col/8];
            if (byte & (0x80 >> (col & 7)))
                NSRectFill(NSMakeRect(ox + col*px, oy + row*px, px, px));
        }
    }
}
